css:
/* ── Nebula — immersive dark glass ─────────────────────────────────────────
   The orb is the centrepiece in voice mode, the transcript sits beneath it,
   and the controls pin to the foot of the panel rather than floating in the
   middle of the stage. Structure comes from CSS only: the DOM is the same one
   every theme gets, so this reaches existing demos through the injected block
   with no rebuild.                                                          */

/* Illuminated edge — the "glass" read, without a backdrop-filter that would
   repaint on every scroll of the customer's page. */
.cds-shell-card {
  border: 1px solid rgba(160,180,255,.14);
  box-shadow: 0 30px 80px rgba(0,0,0,.55), inset 0 1px 0 rgba(190,205,255,.10);
}

/* The voice pane becomes: header, orb stage, transcript, controls. */
.cds-voice { display: flex; flex-direction: column; }
.cds-vheader { background: transparent; border-bottom: 1px solid var(--line); }

/*
   The mock puts the controls at the FOOT of the panel, below the transcript.
   CSS order alone cannot do that: .cds-vcontrols is a child of .cds-vstage
   while .cds-transcript is its sibling, so they are not in the same ordering
   context. display:contents dissolves the stage so its children become direct
   children of .cds-voice — then one flex order lays out orb, transcript,
   controls exactly as drawn. The stage's own padding and background move up to
   .cds-voice, since a display:contents box paints nothing.
*/
.cds-voice {
  padding: 0; background: transparent;
  display: flex; flex-direction: column;
}
.cds-vstage { display: contents; }

.cds-orb { order: 2; margin: 30px auto 8px; }
.cds-verror { order: 3; margin: 0 16px; }
.cds-transcript { order: 4; }
.cds-vcontrols { order: 5; }
.cds-micnote { order: 6; }
/* Nothing else in the stage should claim the free space. */
.cds-vheader { order: 1; }
.cds-orb { width: 154px; height: 154px; }
/* A soft halo behind the orb, so it reads as luminous rather than flat. */
.cds-orb::before {
  content: ""; position: absolute; inset: -22%; border-radius: 50%;
  background: radial-gradient(circle, rgba(110,168,255,.30), rgba(110,168,255,0) 68%);
  pointer-events: none;
}

/* Transcript takes the room the controls used to sit in. */
.cds-transcript {
  flex: 1 1 auto; max-height: none; min-height: 0;
  background: transparent; border-top: 1px solid var(--line);
}

/* Controls pinned at the foot, as one row, always visible. */
.cds-vcontrols {
  flex: 0 0 auto; justify-content: center;
  padding: 16px 16px 6px; gap: 18px;
  border-top: 1px solid var(--line);
}
.cds-micnote { flex: 0 0 auto; padding: 0 0 14px; text-align: center; }

/* Tabs read as a segmented selector rather than loose pills. */
.cds-tabs {
  background: transparent; border-bottom: 1px solid var(--line);
  padding: 10px 12px;
}
.cds-tabs button { background: transparent; border-color: var(--line); }
.cds-tabs button.on {
  background: rgba(110,168,255,.14);
  border-color: rgba(110,168,255,.45);
  box-shadow: 0 0 0 1px rgba(110,168,255,.18), 0 0 18px rgba(110,168,255,.18);
}

/* Chat mode reduces the orb's prominence by not being the orb at all — the
   composer is the focus, so give it the same illuminated treatment. */
.cds-composer { background: transparent; border-top: 1px solid var(--line); }
.cds-composer input { border-color: var(--line); }
.cds-composer input:focus { border-color: rgba(110,168,255,.55); }
